css:
.pa-paper {
	font-family: Arial, Helvetica, sans-serif;
	color: #4a4a4a;
	font-size: 9pt;
	-webkit-print-color-adjust: exact !important;
	print-color-adjust: exact !important;
}
.pa-page-1 { page-break-after: always; }
.pa-page-2 { page-break-before: always; }
.pa-logo-row { width: 100% !important; border-collapse: collapse !important; margin-bottom: 8px; }
.pa-logo-row td { border: none !important; background: transparent !important; padding: 0 !important; }
.pa-hse {
	width: 58px;
	height: 58px;
	border: 3px solid #27569d;
	background: #27569d !important;
	color: #fff !important;
	text-align: center;
}
.pa-main-title { font-size: 18pt; font-weight: 800; text-align: center; }
.pa-orange-text { color: #f58220; }
.pa-blue-text { color: #27569d; }
.pa-subtitle { color: #27569d; font-size: 11pt; font-weight: 700; text-align: center; margin-bottom: 8px; }
.pa-info { width: 100% !important; border-collapse: collapse !important; table-layout: fixed; margin-bottom: 8px; }
.pa-info td { border: 1px solid #555 !important; padding: 4px 7px !important; }
.pa-info-label { width: 18%; background: #27569d !important; color: #fff !important; font-weight: 700; }
.pa-unit-title { background: #f58220 !important; color: #fff !important; padding: 5px 8px; font-weight: 700; }
.pa-grid { width: 100% !important; border-collapse: collapse !important; table-layout: fixed; }
.pa-grid th, .pa-grid td { border: 1px solid #444 !important; }
.pa-grid th { background: #27569d !important; color: #fff !important; }
.pa-outcome { background: #27569d !important; color: #fff !important; font-weight: 700; padding: 6px !important; }
.pa-num { color: #f58220; font-weight: 700; }
.pa-result { text-align: center; font-weight: 700; text-transform: uppercase; }
.pa-guidance-label { background: #27569d !important; color: #fff !important; font-weight: 700; text-align: center; }
.pa-footer-company { color: #27569d; text-align: right; font-weight: 700; }
.pa-remarks-title, .pa-field-title { color: #27569d; font-weight: 700; text-decoration: underline; }
.pa-evidence-bar { background: #ddd !important; padding: 7px 10px; }
.pa-sign-table { width: 100% !important; border-collapse: collapse !important; }
.pa-sign-table th { background: #f58220 !important; color: #fff !important; }
.pa-sign-table td { border: 1px solid #555 !important; height: 62px; text-align: center; }
.pa-sign-name { width: 26%; }
.pa-sign-signature { width: 24%; }
.pa-sign-candidate { width: 24%; }
.pa-sign-date { width: 16%; }
.pa-sign-img { max-height: 48px; max-width: 150px; }
